INSERT INTO festivals (slug, name_en, name_hi, description_en, description_hi, typical_month, lunar_tithi_desc, next_observed_date, region, needs_local_review) VALUES ('maha-shivratri', 'Maha Shivratri', 'महाशिवरात्रि', 'The great night of Lord Shiva. Devotees offer Bilva leaves, Dhatura fruits, and white/blue flowers for the auspicious Lingam Abhishekam.', 'भगवान शिव का पावन महापर्व। शिवलिंग अभिषेक के लिए बेलपत्र, धतूरा, आक और कनेर के पुष्प विशेष रूप से अर्पित किए जाते हैं।', 2, 'Phalguna Krishna Chaturdashi', '2027-03-06', 'All India', true) ON CONFLICT (slug) DO NOTHING;
INSERT INTO festival_plants (festival_id, species_id, purpose, part_needed, is_essential, needs_local_review) SELECT f.id, s.id, 'Primary offering to Shiva Lingam; symbolizes the Trinetra (3 eyes)', 'Intact trifoliate leaves (Belpatra)', true, false FROM festivals f, species s WHERE f.slug = 'maha-shivratri' AND s.scientific_name = 'Aegle marmelos' ON CONFLICT DO NOTHING;
INSERT INTO festival_plants (festival_id, species_id, purpose, part_needed, is_essential, needs_local_review) SELECT f.id, s.id, 'Sacred offering to neutralize cosmic poisons (Halahala)', 'Fruit and flower', true, false FROM festivals f, species s WHERE f.slug = 'maha-shivratri' AND s.scientific_name = 'Datura metel' ON CONFLICT DO NOTHING;
INSERT INTO festival_plants (festival_id, species_id, purpose, part_needed, is_essential, needs_local_review) SELECT f.id, s.id, 'Offering of sacred white/purple flowers and garland to Shiva', 'Flowers (Aak/Madar ke phool)', false, false FROM festivals f, species s WHERE f.slug = 'maha-shivratri' AND s.scientific_name = 'Calotropis procera' ON CONFLICT DO NOTHING;
INSERT INTO festival_plants (festival_id, species_id, purpose, part_needed, is_essential, needs_local_review) SELECT f.id, s.id, 'Offering of vibrant fragrant flowers', 'Flowers (Kaner)', false, false FROM festivals f, species s WHERE f.slug = 'maha-shivratri' AND s.scientific_name = 'Nerium oleander' ON CONFLICT DO NOTHING;
INSERT INTO festival_plants (festival_id, species_id, purpose, part_needed, is_essential, needs_local_review) SELECT f.id, s.id, 'Traditional Shami leaf offering to Lord Shiva', 'Fresh leaves', false, false FROM festivals f, species s WHERE f.slug = 'maha-shivratri' AND s.scientific_name = 'Prosopis cineraria' ON CONFLICT DO NOTHING;
INSERT INTO festivals (slug, name_en, name_hi, description_en, description_hi, typical_month, lunar_tithi_desc, next_observed_date, region, needs_local_review) VALUES ('dussehra', 'Dussehra (Vijayadashami)', 'दशहरा (विजयादशमी)', 'Celebration of the victory of righteousness over evil. Exchanging Shami and Apta leaves symbolizes mutual prosperity ("Gold exchange").', 'बुराई पर अच्छाई की विजय का पर्व। शमी और आप्टा के पत्तों को "सोना" मानकर एक-दूसरे को आदरपूर्वक भेंट करने की परंपरा है।', 10, 'Ashvina Shukla Dashami', '2027-10-10', 'All India', true) ON CONFLICT (slug) DO NOTHING;
INSERT INTO festival_plants (festival_id, species_id, purpose, part_needed, is_essential, needs_local_review) SELECT f.id, s.id, 'Auspicious Shami leaves for greeting elders and friends as "Son-patta"', 'Fresh leaflets', true, false FROM festivals f, species s WHERE f.slug = 'dussehra' AND s.scientific_name = 'Prosopis cineraria' ON CONFLICT DO NOTHING;
INSERT INTO festival_plants (festival_id, species_id, purpose, part_needed, is_essential, needs_local_review) SELECT f.id, s.id, 'Mango leaves for doorstep Toran to welcome prosperity', 'Fresh leaves', true, false FROM festivals f, species s WHERE f.slug = 'dussehra' AND s.scientific_name = 'Mangifera indica' ON CONFLICT DO NOTHING;
INSERT INTO festivals (slug, name_en, name_hi, description_en, description_hi, typical_month, lunar_tithi_desc, next_observed_date, region, needs_local_review) VALUES ('ganesh-chaturthi', 'Ganesh Chaturthi', 'गणेश चतुर्थी', 'Welcoming Lord Ganesha with the traditional 21-sacred leaf (Eka-vimshati Patrika) and Durva grass rituals.', 'भगवान गणेश का जन्मोत्सव। 21 प्रकार के पवित्र पत्रों (एकविंशति पत्रिका) और दूर्वा की 21 गांठों से विशेष पूजन किया जाता है।', 9, 'Bhadrapada Shukla Chaturthi', '2027-09-04', 'All India', true) ON CONFLICT (slug) DO NOTHING;
INSERT INTO festival_plants (festival_id, species_id, purpose, part_needed, is_essential, needs_local_review) SELECT f.id, s.id, 'Indispensable 21 Durva grass bunches offered to Ganesha', 'Tender 3-bladed nodes', true, false FROM festivals f, species s WHERE f.slug = 'ganesh-chaturthi' AND s.scientific_name = 'Cynodon dactylon' ON CONFLICT DO NOTHING;
INSERT INTO festival_plants (festival_id, species_id, purpose, part_needed, is_essential, needs_local_review) SELECT f.id, s.id, 'Lord Ganesha''s most beloved red flower (Rakta Pushpa)', 'Fresh red blossoms', true, false FROM festivals f, species s WHERE f.slug = 'ganesh-chaturthi' AND s.scientific_name = 'Hibiscus rosa-sinensis' ON CONFLICT DO NOTHING;
INSERT INTO festival_plants (festival_id, species_id, purpose, part_needed, is_essential, needs_local_review) SELECT f.id, s.id, 'Part of the 21 Patrika sacred botanical set', 'Trifoliate leaves (Bilvapatra)', true, false FROM festivals f, species s WHERE f.slug = 'ganesh-chaturthi' AND s.scientific_name = 'Aegle marmelos' ON CONFLICT DO NOTHING;
INSERT INTO festival_plants (festival_id, species_id, purpose, part_needed, is_essential, needs_local_review) SELECT f.id, s.id, 'Shami patra for Ganesha Sahasranama puja', 'Leaves', true, false FROM festivals f, species s WHERE f.slug = 'ganesh-chaturthi' AND s.scientific_name = 'Prosopis cineraria' ON CONFLICT DO NOTHING;
INSERT INTO festivals (slug, name_en, name_hi, description_en, description_hi, typical_month, lunar_tithi_desc, next_observed_date, region, needs_local_review) VALUES ('diwali', 'Diwali & Dhanteras', 'दीपावली एवं धनतेरस', 'Festival of lights. Homes are adorned with entrance Torans crafted from fresh Mango and Ashoka leaves to invite Goddess Lakshmi.', 'दीपोत्सव एवं माता लक्ष्मी का आगमन पर्व। घर के मुख्य द्वार पर आम और अशोक के पत्तों का तोरण बांधना अत्यंत शुभ माना जाता है।', 11, 'Kartika Amavasya', '2027-10-29', 'All India', true) ON CONFLICT (slug) DO NOTHING;
INSERT INTO festival_plants (festival_id, species_id, purpose, part_needed, is_essential, needs_local_review) SELECT f.id, s.id, 'Entrance Toran and Kalash Sthapana for Lakshmi Puja', 'Fresh green leaves', true, false FROM festivals f, species s WHERE f.slug = 'diwali' AND s.scientific_name = 'Mangifera indica' ON CONFLICT DO NOTHING;
INSERT INTO festival_plants (festival_id, species_id, purpose, part_needed, is_essential, needs_local_review) SELECT f.id, s.id, 'Tulsi leaves for offering to Lord Vishnu & Dhanvantari', 'Fresh leaves and Manjari (flower spikes)', true, false FROM festivals f, species s WHERE f.slug = 'diwali' AND s.scientific_name = 'Ocimum tenuiflorum' ON CONFLICT DO NOTHING;
INSERT INTO festivals (slug, name_en, name_hi, description_en, description_hi, typical_month, lunar_tithi_desc, next_observed_date, region, needs_local_review) VALUES ('chhath-puja', 'Chhath Puja', 'छठ पूजा', 'Ancient solar thanksgiving festival celebrated with profound reverence along riverbanks. Offerings comprise pure, unhybridized agricultural plants.', 'सूर्यदेव एवं छठी मइया का महापर्व। सूप और दउरा में ईख, अदरक का पौधा, हल्दी का पौधा, केला और बेल फल अर्पित किए जाते हैं।', 11, 'Kartika Shukla Shashthi', '2027-11-04', 'Bihar, Jharkhand, UP & Global Purvanchal', true) ON CONFLICT (slug) DO NOTHING;
INSERT INTO festival_plants (festival_id, species_id, purpose, part_needed, is_essential, needs_local_review) SELECT f.id, s.id, 'Offering of sacred Bael fruit in the Daura/Arghya', 'Whole hard-shelled fruit', true, false FROM festivals f, species s WHERE f.slug = 'chhath-puja' AND s.scientific_name = 'Aegle marmelos' ON CONFLICT DO NOTHING;
INSERT INTO festival_plants (festival_id, species_id, purpose, part_needed, is_essential, needs_local_review) SELECT f.id, s.id, 'Dry mango wood for the pristine Havana and sacred stove fire', 'Fallen dry twigs and branches', true, false FROM festivals f, species s WHERE f.slug = 'chhath-puja' AND s.scientific_name = 'Mangifera indica' ON CONFLICT DO NOTHING;
INSERT INTO festivals (slug, name_en, name_hi, description_en, description_hi, typical_month, lunar_tithi_desc, next_observed_date, region, needs_local_review) VALUES ('tulsi-vivah', 'Tulsi Vivah', 'तुलसी विवाह', 'Ceremonial marriage of the Holy Basil (Tulsi) with Lord Vishnu (Shaligrama), inaugurating the Hindu wedding season.', 'तुलसी जी का भगवान शालिग्राम के साथ दिव्य विवाह। इस दिन से मांगलिक कार्यों और विवाह का शुभारंभ होता है।', 11, 'Kartika Shukla Ekadashi / Dvadashi', '2027-11-10', 'All India', true) ON CONFLICT (slug) DO NOTHING;
INSERT INTO festival_plants (festival_id, species_id, purpose, part_needed, is_essential, needs_local_review) SELECT f.id, s.id, 'The central deity of the ceremony', 'Living potted plant adorned as a bride', true, false FROM festivals f, species s WHERE f.slug = 'tulsi-vivah' AND s.scientific_name = 'Ocimum tenuiflorum' ON CONFLICT DO NOTHING;
INSERT INTO festival_plants (festival_id, species_id, purpose, part_needed, is_essential, needs_local_review) SELECT f.id, s.id, 'Amla branch placed in the Tulsi pot representing Vishnu', 'Tender branch with leaves and gooseberry fruit', true, false FROM festivals f, species s WHERE f.slug = 'tulsi-vivah' AND s.scientific_name = 'Phyllanthus emblica' ON CONFLICT DO NOTHING;
INSERT INTO festivals (slug, name_en, name_hi, description_en, description_hi, typical_month, lunar_tithi_desc, next_observed_date, region, needs_local_review) VALUES ('vat-savitri', 'Vat Savitri Vrat', 'वट सावित्री व्रत', 'Married women observe fast and pray around the sacred Banyan tree for marital bliss and spouse''s longevity, commemorating Savitri''s devotion.', 'सुहागिन महिलाओं द्वारा पति की दीर्घायु और अखंड सौभाग्य हेतु वट (बरगद) वृक्ष की परिक्रमा और सूत बांधने का पावन व्रत।', 6, 'Jyeshtha Amavasya / Purnima', '2027-06-04', 'All India (North, West & Central)', true) ON CONFLICT (slug) DO NOTHING;
INSERT INTO festival_plants (festival_id, species_id, purpose, part_needed, is_essential, needs_local_review) SELECT f.id, s.id, 'Living Banyan tree for parikrama (circumambulation) and thread wrapping', 'Standing living tree', true, false FROM festivals f, species s WHERE f.slug = 'vat-savitri' AND s.scientific_name = 'Ficus benghalensis' ON CONFLICT DO NOTHING;
INSERT INTO festivals (slug, name_en, name_hi, description_en, description_hi, typical_month, lunar_tithi_desc, next_observed_date, region, needs_local_review) VALUES ('ugadi-gudi-padwa', 'Ugadi / Gudi Padwa', 'उगादि / गुड़ी पड़वा', 'Deccan and Marathi New Year celebration. Neem leaves and flowers are mixed with jaggery to symbolize life''s dual experiences of bitter and sweet.', 'नववर्ष उत्सव। जीवन के सुख-दुख का प्रतीक माने जाने वाले नीम के पत्ते और फूल गुड़ के साथ ग्रहण किए जाते हैं।', 4, 'Chaitra Shukla Pratipada', '2027-04-07', 'Karnataka, Andhra Pradesh, Telangana, Maharashtra', true) ON CONFLICT (slug) DO NOTHING;
INSERT INTO festival_plants (festival_id, species_id, purpose, part_needed, is_essential, needs_local_review) SELECT f.id, s.id, 'Essential ingredient for Ugadi Pachadi / Bevu-Bella', 'Tender fresh leaves and small white flowers', true, false FROM festivals f, species s WHERE f.slug = 'ugadi-gudi-padwa' AND s.scientific_name = 'Azadirachta indica' ON CONFLICT DO NOTHING;
INSERT INTO festival_plants (festival_id, species_id, purpose, part_needed, is_essential, needs_local_review) SELECT f.id, s.id, 'Fresh green mangoes for Pachadi and entrance Toran', 'Unripe green mango & leaves', true, false FROM festivals f, species s WHERE f.slug = 'ugadi-gudi-padwa' AND s.scientific_name = 'Mangifera indica' ON CONFLICT DO NOTHING;
INSERT INTO festivals (slug, name_en, name_hi, description_en, description_hi, typical_month, lunar_tithi_desc, next_observed_date, region, needs_local_review) VALUES ('navratri-durga-puja', 'Navratri & Durga Puja (Navapatrika)', 'नवरात्रि एवं दुर्गा पूजा (नवपत्रिका)', 'Worship of the 9 sacred plants (Navapatrika / Kola Bou) embodying 9 manifestations of Goddess Durga.', 'माँ दुर्गा के नौ रूपों का प्रतीक मानी जाने वाली नौ पवित्र वनस्पतियों (नवपत्रिका) का विधिवत आवाहन एवं पूजन।', 10, 'Ashvina Shukla Saptami', '2027-10-07', 'Bengal, Assam, Odisha, All India', true) ON CONFLICT (slug) DO NOTHING;
INSERT INTO festival_plants (festival_id, species_id, purpose, part_needed, is_essential, needs_local_review) SELECT f.id, s.id, 'Belpatrika: Invocation of Goddess Shivaa', 'Trifoliate leaves on a twig', true, false FROM festivals f, species s WHERE f.slug = 'navratri-durga-puja' AND s.scientific_name = 'Aegle marmelos' ON CONFLICT DO NOTHING;
INSERT INTO festival_plants (festival_id, species_id, purpose, part_needed, is_essential, needs_local_review) SELECT f.id, s.id, 'Ashoka: Invocation of Goddess Shokarahita', 'Branch with tender leaves', true, false FROM festivals f, species s WHERE f.slug = 'navratri-durga-puja' AND s.scientific_name = 'Saraca asoca' ON CONFLICT DO NOTHING;
INSERT INTO festival_plants (festival_id, species_id, purpose, part_needed, is_essential, needs_local_review) SELECT f.id, s.id, 'Daily Pushpanjali to Mother Durga', 'Red Gudhal / Jaba flowers', true, false FROM festivals f, species s WHERE f.slug = 'navratri-durga-puja' AND s.scientific_name = 'Hibiscus rosa-sinensis' ON CONFLICT DO NOTHING;
INSERT INTO festivals (slug, name_en, name_hi, description_en, description_hi, typical_month, lunar_tithi_desc, next_observed_date, region, needs_local_review) VALUES ('makar-sankranti', 'Makar Sankranti & Pongal', 'मकर संक्रांति एवं पोंगल', 'Harvest festival celebrating the sun transition into Capricorn. Festive cooking incorporates freshly harvested herbs and leaves.', 'सूर्य के मकर राशि में प्रवेश का पावन सूर्योत्सव एवं फसलों का त्योहार।', 1, 'Solar ingress (Makara Sankranti)', '2027-01-14', 'All India', true) ON CONFLICT (slug) DO NOTHING;
INSERT INTO festival_plants (festival_id, species_id, purpose, part_needed, is_essential, needs_local_review) SELECT f.id, s.id, 'Entrance decor and festive mango-leaf torans', 'Leaves', true, false FROM festivals f, species s WHERE f.slug = 'makar-sankranti' AND s.scientific_name = 'Mangifera indica' ON CONFLICT DO NOTHING;
INSERT INTO festivals (slug, name_en, name_hi, description_en, description_hi, typical_month, lunar_tithi_desc, next_observed_date, region, needs_local_review) VALUES ('raksha-bandhan', 'Raksha Bandhan & Shravani Upakarma', 'रक्षाबंधन एवं श्रावणी उपाकर्म', 'Celebration of sibling bonds and Vedic Upakarma ritual using sacred Durva and Tulsi for sanctification.', 'भाई-बहन के स्नेह और रक्षा का पर्व तथा पवित्र यज्ञोपवीत उपाकर्म पूजन।', 8, 'Shravana Purnima', '2027-08-17', 'All India', true) ON CONFLICT (slug) DO NOTHING;
INSERT INTO festival_plants (festival_id, species_id, purpose, part_needed, is_essential, needs_local_review) SELECT f.id, s.id, 'Auspicious grass placed in the Rakhi thali and Akshata', 'Fresh green Durva blades', true, false FROM festivals f, species s WHERE f.slug = 'raksha-bandhan' AND s.scientific_name = 'Cynodon dactylon' ON CONFLICT DO NOTHING;
INSERT INTO festival_plants (festival_id, species_id, purpose, part_needed, is_essential, needs_local_review) SELECT f.id, s.id, 'Offering during morning puja rituals', 'Fresh leaves', true, false FROM festivals f, species s WHERE f.slug = 'raksha-bandhan' AND s.scientific_name = 'Ocimum tenuiflorum' ON CONFLICT DO NOTHING;
INSERT INTO festivals (slug, name_en, name_hi, description_en, description_hi, typical_month, lunar_tithi_desc, next_observed_date, region, needs_local_review) VALUES ('guru-purnima', 'Guru Purnima / Buddha Purnima', 'गुरु पूर्णिमा / बुद्ध पूर्णिमा', 'Reverence to spiritual preceptors and commemoration of Buddha''s enlightenment under the Bodhi tree.', 'आध्यात्मिक गुरुओं के प्रति कृतज्ञता तथा बोधिवृक्ष के नीचे भगवान बुद्ध के ज्ञानोदय का स्मरण।', 7, 'Ashadha Purnima / Vaishakha Purnima', '2027-07-18', 'All India', true) ON CONFLICT (slug) DO NOTHING;
INSERT INTO festival_plants (festival_id, species_id, purpose, part_needed, is_essential, needs_local_review) SELECT f.id, s.id, 'Meditation, circumambulation, and honor to the Bodhi lineage', 'Living Peepal tree', true, false FROM festivals f, species s WHERE f.slug = 'guru-purnima' AND s.scientific_name = 'Ficus religiosa' ON CONFLICT DO NOTHING;
INSERT INTO plants (species_id, location, fuzzed_location, address_hint, land_type, private_owner_consent, notes, source, attribution, license, status, is_sacred_heritage, heritage_story) SELECT id, ST_SetSRID(ST_MakePoint(83.0107, 25.3109), 4326)::geography, ST_SetSRID(ST_MakePoint(83, 25.3), 4326)::geography, 'Near Assi Ghat entrance pathway, under stone pavilion', 'temple', false, 'Mature Bael tree with abundant trifoliate leaves, revered by local morning bathers and pujaris.', 'community', 'Kashi Heritage Trust (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'recently_verified', true, 'Planted over 60 years ago; devotees collect Belpatra for morning Vishwanath offerings.' FROM species WHERE scientific_name = 'Aegle marmelos' ON CONFLICT DO NOTHING;
INSERT INTO plants (species_id, location, fuzzed_location, address_hint, land_type, private_owner_consent, notes, source, attribution, license, status, is_sacred_heritage, heritage_story) SELECT id, ST_SetSRID(ST_MakePoint(83.0072, 25.3085), 4326)::geography, ST_SetSRID(ST_MakePoint(83, 25.3), 4326)::geography, 'Tulsi Ghat, adjacent to Akhada platform', 'public', false, 'Massive sacred Peepal overlooking the Ganga river steps. Excellent cooling shade.', 'community', 'Ghat Conservation Volunteer', 'CC BY-SA 4.0', 'recently_verified', true, 'Associated with Goswami Tulsidas tradition along the Ghats.' FROM species WHERE scientific_name = 'Ficus religiosa' ON CONFLICT DO NOTHING;
